var clk = create("clock", { f: 2 });
var cnt = create("counter4", { mod: 16 });
var probes = [];
for (var i = 0; i < 4; i++) {
    var probe = create("logic-probe", { name: "Q" + i });
    connect(cnt["q" + i], probe.terminal);
    probes.push(probe);
}
connect(clk.out, cnt.clk);

var mux = create("mux", { x: 200, y: 180 });
addproperty(mux, "showTrail", true);

// Create input signals
var inputs = [];
for (var i = 0; i < 4; i++) {
    var input = create("input", { x: 50 + i * 70, y: 200, value: Math.random() });
    addproperty(input, "showTrail", true);
    inputs.push(input);
}

// Create select signals
var selectSignals = [];
for (var i = 0; i < 2; i++) {
    var selectSignal = create("input", { x: 50 + i * 70, y: 300, value: Math.random() });
    addproperty(selectSignal, "showTrail", true);
    selectSignals.push(selectSignal);
}

// Connect inputs to the multiplexer
for (var i = 0; i < 4; i++) {
    connect(inputs[i].output, mux.input[i]);
}

// Connect select signals to the multiplexer
for (var i = 0; i < 2; i++) {
    connect(selectSignals[i].output, mux.select[i]);
}

// Create an output probe
var outputProbe = create("probe", { x: 350, y: 180 });
connect(mux.output, outputProbe.input);

// Add a table to display the inputs and select signals
var table = create("table", {
    x: 20,
    y: 400,
    headers: ["Input", "Select", "Output"],
    data: [
        [inputs[0].value, selectSignals[0].value, outputProbe.value],
        [inputs[1].value, selectSignals[1].value, outputProbe.value]
    ]
});

